"use client";

import { useMemo, useState } from "react";
import {
  Box,
  Typography,
  Button,
  Grid,
  Card,
  CardContent,
  Divider,
  Paper,
} from "@mui/material";
import {
  ArrowBack,
  Home,
  Person,
  AttachMoney,
  CalendarToday,
  Email,
  Phone,
  Payments,
  Check,
} from "@mui/icons-material";
import { useMortgageData } from "../context/MortgageContext";
import Swal from "sweetalert2";
import PropTypes from "prop-types";
import { useTheme } from "@mui/material/styles";

const SummaryCard = ({ title, icon, children }) => (
  <Card
    sx={{
      borderRadius: 2,
      boxShadow: "0 2px 12px rgba(0,0,0,0.08)",
      background: "rgba(191, 239, 255, 0.39)",
    }}
    role="region"
    aria-labelledby={`${title.replace(/\s+/g, "-").toLowerCase()}-heading`}
  >
    <CardContent>
      <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
        {icon}
        <Typography
          id={`${title.replace(/\s+/g, "-").toLowerCase()}-heading`}
          variant="h6"
          fontWeight="bold"
        >
          {title}
        </Typography>
      </Box>
      <Divider sx={{ mb: 2 }} />
      {children}
    </CardContent>
  </Card>
);

function DataSummary({ onBack, onSubmit }) {
  const { mortgageData } = useMortgageData();
  const theme = useTheme();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const requiredFields = [
    "propertyAddress",
    "propertyType",
    "propertySize",
    "borrowerName",
    "email",
    "phone",
    "loanAmount",
    "interestRate",
    "loanTerm",
  ];

  const isDataValid = requiredFields.every(
    (field) => mortgageData[field] && mortgageData[field].toString().trim() !== ""
  );

  const calculateMonthlyPayment = useMemo(() => {
    const principal = Number.parseFloat(mortgageData.loanAmount) || 300000;
    const interestRate = (Number.parseFloat(mortgageData.interestRate) || 3.5) / 100 / 12;
    const numberOfPayments = (Number.parseInt(mortgageData.loanTerm) || 30) * 12;

    if (principal <= 0 || interestRate <= 0 || numberOfPayments <= 0) {
      return 0;
    }

    const monthlyPayment =
      (principal * interestRate * Math.pow(1 + interestRate, numberOfPayments)) /
      (Math.pow(1 + interestRate, numberOfPayments) - 1);

    return Math.round(monthlyPayment);
  }, [mortgageData.loanAmount, mortgageData.interestRate, mortgageData.loanTerm]);

  const totalPayment = calculateMonthlyPayment * (Number.parseInt(mortgageData.loanTerm) || 30) * 12;

  const handleSubmitClick = async () => {
    const result = await Swal.fire({
      title: "Submit Application?",
      text: "Are you sure you want to submit this mortgage application?",
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#1976d2",
      cancelButtonColor: "#d32f2f",
      confirmButtonText: "Yes, submit it!",
      cancelButtonText: "Review again",
    });

    if (result.isConfirmed) {
      setIsSubmitting(true);
      try {
        await Swal.fire({
          title: "Processing...",
          text: "Your application is being submitted",
          timer: 1500,
          timerProgressBar: true,
          didOpen: () => {
            Swal.showLoading();
          },
        });
        await onSubmit();
        await Swal.fire({
          title: "Success!",
          text: "Mortgage application submitted successfully!",
          icon: "success",
          confirmButtonColor: "#1976d2",
        });
      } catch (error) {
        await Swal.fire({
          title: "Error!",
          text: "Failed to submit the application. Please try again.",
          icon: "error",
          confirmButtonColor: "#d32f2f",
        });
      } finally {
        setIsSubmitting(false);
      }
    }
  };

  if (!isDataValid) {
    return (
      <Box sx={{ maxWidth: 800, mx: "auto", textAlign: "center" }}>
        <Typography variant="h4" color="error.main" gutterBottom>
          Incomplete Data
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 4 }}>
          Please fill out all required fields before reviewing the summary.
        </Typography>
        <Button
          onClick={onBack}
          variant="outlined"
          color="primary"
          size="large"
          startIcon={<ArrowBack />}
          aria-label="Go back to previous step"
        >
          Go Back
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ maxWidth: 800, mx: "auto" }}>
      <Typography
        variant="h4"
        component="h2"
        gutterBottom
        fontWeight="bold"
        color="primary.main"
      >
        Data Summary
      </Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 4 }}>
        Review your mortgage information before submission
      </Typography>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <SummaryCard
            title="Property Details"
            icon={<Home color="primary" sx={{ mr: 1 }} />}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Address
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.propertyAddress}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Type
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.propertyType}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Size
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.propertySize}
                </Typography>
              </Grid>
            </Grid>
          </SummaryCard>
        </Grid>

        <Grid item xs={12}>
          <SummaryCard
            title="Personal Information"
            icon={<Person color="primary" sx={{ mr: 1 }} />}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Name
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.borrowerName}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Email
                </Typography>
                <Box sx={{ display: "flex", alignItems: "center" }}>
                  <Email fontSize="small" sx={{ mr: 0.5, color: "text.secondary" }} />
                  <Typography variant="body1" fontWeight="medium">
                    {mortgageData.email}
                  </Typography>
                </Box>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Phone
                </Typography>
                <Box sx={{ display: "flex", alignItems: "center" }}>
                  <Phone fontSize="small" sx={{ mr: 0.5, color: "text.secondary" }} />
                  <Typography variant="body1" fontWeight="medium">
                    {mortgageData.phone}
                  </Typography>
                </Box>
              </Grid>
            </Grid>
          </SummaryCard>
        </Grid>

        <Grid item xs={12}>
          <SummaryCard
            title="Loan Specifics"
            icon={<AttachMoney color="primary" sx={{ mr: 1 }} />}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Loan Amount
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  ${Number(mortgageData.loanAmount).toLocaleString()}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Interest Rate
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {`${Number.parseFloat(mortgageData.interestRate).toFixed(2)}%`}
                </Typography>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Typography variant="body2" color="text.secondary">
                  Term
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.loanTerm} years
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary">
                  Transaction Date
                </Typography>
                <Box sx={{ display: "flex", alignItems: "center" }}>
                  <CalendarToday fontSize="small" sx={{ mr: 0.5, color: "text.secondary" }} />
                  <Typography variant="body1" fontWeight="medium">
                    {mortgageData.transactionDate || "Not specified"}
                  </Typography>
                </Box>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary">
                  Loan Officer
                </Typography>
                <Typography variant="body1" fontWeight="medium">
                  {mortgageData.loanOfficerName || "Not specified"}
                </Typography>
              </Grid>
            </Grid>
          </SummaryCard>
        </Grid>

        <Grid item xs={12}>
          <SummaryCard
            title="Payment Breakdown"
            icon={<Payments color="primary" sx={{ mr: 1 }} />}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <Paper
                  sx={{
                    p: 3,
                    borderRadius: 2,
                    background: theme.palette.primary.main,
                    color: theme.palette.primary.contrastText,
                    boxShadow: "0 4px 20px rgba(0, 0, 0, 0.1)",
                  }}
                >
                  <Typography variant="body2">Monthly Payment</Typography>
                  <Typography variant="h4" fontWeight="bold" sx={{ mt: 1 }}>
                    ${calculateMonthlyPayment.toLocaleString()}
                  </Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Paper
                  sx={{
                    p: 3,
                    borderRadius: 2,
                    background: theme.palette.secondary.main,
                    color: theme.palette.secondary.contrastText,
                    boxShadow: "0 4px 20px rgba(0, 0, 0, 0.1)",
                  }}
                >
                  <Typography variant="body2">Total Payment</Typography>
                  <Typography variant="h4" fontWeight="bold" sx={{ mt: 1 }}>
                    ${totalPayment.toLocaleString()}
                  </Typography>
                </Paper>
              </Grid>
            </Grid>
          </SummaryCard>
        </Grid>
      </Grid>

      <Box sx={{ mt: 4, display: "flex", justifyContent: "space-between" }}>
        <Button
          onClick={onBack}
          variant="outlined"
          color="primary"
          size="large"
          sx={{ minWidth: 150 }}
          startIcon={<ArrowBack />}
          aria-label="Go back to previous step"
        >
          Back
        </Button>
        <Button
          variant="contained"
          color="primary"
          size="large"
          sx={{ minWidth: 150 }}
          onClick={handleSubmitClick}
          disabled={isSubmitting}
          startIcon={<Check />}
        >
          {isSubmitting ? "Submitting..." : "Submit"}
        </Button>
      </Box>
    </Box>
  );
}

DataSummary.propTypes = {
  onBack: PropTypes.func.isRequired,
  onSubmit: PropTypes.func.isRequired,
};

export default DataSummary;