"use client";

import { useState } from "react";
import {
  Box,
  Typography,
  TextField,
  Button,
  Grid,
  MenuItem,
  Select,
  InputLabel,
  FormControl,
  Paper,
  Collapse,
  IconButton,
  InputAdornment,
  Card,
  CardContent,
} from "@mui/material";
import { DatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import {
  ExpandMore,
  ExpandLess,
  CalendarMonth,
  Person,
  Badge,
  AttachMoney,
  Home,
  Description,
  ArrowForward,
} from "@mui/icons-material";
import { useMortgageData } from "../context/MortgageContext";
import { useTheme } from "@mui/material/styles";
import PropTypes from "prop-types";
import { parse, isValid } from "date-fns";

const SectionCard = ({ title, children }) => (
  <Card sx={{ mb: 4, borderRadius: 2, boxShadow: "0 2px 12px rgba(0,0,0,0.08)" }}>
    <CardContent>
      <Typography variant="h6" gutterBottom fontWeight="bold" color="primary.main">
        {title}
      </Typography>
      <Grid container spacing={3}>
        {children}
      </Grid>
    </CardContent>
  </Card>
);

const FormTextField = ({ label, name, value, onChange, error, helperText, icon, type = "text", inputProps }) => (
  <Grid item xs={12} sm={type === "number" ? 4 : 6}>
    <TextField
      required
      fullWidth
      label={label}
      name={name}
      type={type}
      value={value}
      onChange={onChange}
      error={!!error}
      helperText={helperText}
      inputProps={inputProps}
      InputProps={{
        startAdornment: icon ? (
          <InputAdornment position="start">{icon}</InputAdornment>
        ) : null,
      }}
    />
  </Grid>
);

const validateForm = (data) => {
  const errors = {};
  if (!data.propertyAddress?.trim()) errors.propertyAddress = "Property address is required";
  if (!data.transactionDate) errors.transactionDate = "Transaction date is required";
  if (!data.borrowerName?.trim()) errors.borrowerName = "Borrower name is required";
  if (!data.loanOfficerName?.trim()) errors.loanOfficerName = "Loan officer name is required";
  if (!data.nmlsId?.trim()) errors.nmlsId = "NMLS ID is required";
  if (!data.loanAmount || data.loanAmount <= 0) errors.loanAmount = "Loan amount must be a positive number";
  if (!data.loanTerm) errors.loanTerm = "Loan term is required";
  if (!data.downPayment || data.downPayment < 0) errors.downPayment = "Down payment must be a non-negative number";
  if (!data.apn?.trim()) errors.apn = "APN is required";
  if (!data.enteredBy?.trim()) errors.enteredBy = "Entered by is required";
  return errors;
};

function MortgageContract({ onNext }) {
  const { mortgageData, updateMortgageData } = useMortgageData();
  const theme = useTheme();
  const [expanded, setExpanded] = useState(false);
  const [date, setDate] = useState(
    mortgageData.transactionDate ? parse(mortgageData.transactionDate, "M/d/yyyy", new Date()) : null
  );
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const safeMortgageData = {
    propertyAddress: mortgageData.propertyAddress || "",
    transactionDate: mortgageData.transactionDate || "",
    borrowerName: mortgageData.borrowerName || "",
    loanOfficerName: mortgageData.loanOfficerName || "",
    nmlsId: mortgageData.nmlsId || "",
    loanAmount: mortgageData.loanAmount || "",
    loanTerm: mortgageData.loanTerm || "",
    downPayment: mortgageData.downPayment || "",
    apn: mortgageData.apn || "",
    enteredBy: mortgageData.enteredBy || "",
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    let sanitizedValue = value;
    if (["loanAmount", "downPayment"].includes(name)) {
      sanitizedValue = value ? Math.max(0, Number(value)) : "";
    }
    updateMortgageData({ [name]: sanitizedValue });
  };

  const handleDateChange = (newDate) => {
    setDate(newDate);
    if (newDate && isValid(newDate)) {
      const formattedDate = newDate.toISOString().split("T")[0];
      updateMortgageData({ transactionDate: formattedDate });
    } else {
      updateMortgageData({ transactionDate: "" });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formErrors = validateForm(safeMortgageData);
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }
    setIsSubmitting(true);
    try {
      await onNext();
      setErrors({});
    } catch (error) {
      setErrors({ general: "Failed to proceed. Please try again." });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit}
      sx={{ maxWidth: 800, mx: "auto" }}
      role="form"
      aria-labelledby="mortgage-contract-heading"
    >
      <Typography
        id="mortgage-contract-heading"
        variant="h4"
        component="h2"
        gutterBottom
        fontWeight="bold"
        color="primary.main"
      >
        Mortgage Contract
      </Typography>
      <Typography variant="body1" color="text.secondary" paragraph sx={{ mb: 4 }}>
        Please fill in the contract details below
      </Typography>

      {errors.general && (
        <Typography color="error" sx={{ mt: 2, textAlign: "center" }}>
          {errors.general}
        </Typography>
      )}

      <Box
        sx={{ mb: 4 }}
        role="region"
        aria-expanded={expanded}
        aria-label="Sample Mortgage Contract"
      >
        <Paper
          sx={{
            p: 2,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            bgcolor: theme.palette.primary.light,
            color: theme.palette.primary.contrastText,
            borderRadius: 2,
            cursor: "pointer",
          }}
          onClick={() => setExpanded(!expanded)}
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              setExpanded(!expanded);
            }
          }}
        >
          <Typography variant="subtitle1" fontWeight="medium">
            View Sample Mortgage Contract
          </Typography>
          <IconButton
            size="small"
            sx={{ color: theme.palette.primary.contrastText }}
            aria-label={expanded ? "Collapse section" : "Expand section"}
          >
            {expanded ? <ExpandLess /> : <ExpandMore />}
          </IconButton>
        </Paper>
        <Collapse in={expanded} timeout="auto" unmountOnExit>
          <Paper sx={{ p: 2, mt: 1, borderRadius: 2 }}>
            <Box
              component="img"
              src="/mortgage_image.png"
              alt="Sample Mortgage Contract"
              onError={(e) => {
                e.target.src = "/fallback_image.png";
              }}
              sx={{
                width: "100%",
                height: "70%",
                borderRadius: 1,
                boxShadow: 2,
              }}
            />
          </Paper>
        </Collapse>
      </Box>

      <SectionCard title="Property Information">
        <FormTextField
          label="Property Address"
          name="propertyAddress"
          value={safeMortgageData.propertyAddress}
          onChange={handleChange}
          error={errors.propertyAddress}
          helperText={errors.propertyAddress}
          icon={<Home color="primary" />}
        />
        <Grid item xs={12} sm={6}>
          <LocalizationProvider dateAdapter={AdapterDateFns}>
            <DatePicker
              label="Transaction Date"
              value={date}
              onChange={handleDateChange}
              slotProps={{
                textField: {
                  fullWidth: true,
                  required: true,
                  error: !!errors.transactionDate,
                  helperText: errors.transactionDate,
                  InputProps: {
                    startAdornment: (
                      <InputAdornment position="start">
                        <CalendarMonth color="primary" />
                      </InputAdornment>
                    ),
                  },
                },
              }}
            />
          </LocalizationProvider>
        </Grid>
        <FormTextField
          label="Borrower/Property Owner Name"
          name="borrowerName"
          value={safeMortgageData.borrowerName}
          onChange={handleChange}
          error={errors.borrowerName}
          helperText={errors.borrowerName}
          icon={<Person color="primary" />}
        />
      </SectionCard>

      <SectionCard title="Loan Officer Details">
        <FormTextField
          label="Loan Officer Name"
          name="loanOfficerName"
          value={safeMortgageData.loanOfficerName}
          onChange={handleChange}
          error={errors.loanOfficerName}
          helperText={errors.loanOfficerName}
          icon={<Person color="primary" />}
        />
        <FormTextField
          label="NMLS ID"
          name="nmlsId"
          value={safeMortgageData.nmlsId}
          onChange={handleChange}
          error={errors.nmlsId}
          helperText={errors.nmlsId}
          icon={<Badge color="primary" />}
        />
      </SectionCard>

      <SectionCard title="Loan Details">
        <FormTextField
          label="Loan Amount"
          name="loanAmount"
          type="number"
          value={safeMortgageData.loanAmount}
          onChange={handleChange}
          error={errors.loanAmount}
          helperText={errors.loanAmount}
          icon={<AttachMoney color="primary" />}
          inputProps={{ min: 0, step: 1 }}
        />
        <Grid item xs={12} sm={4}>
          <FormControl fullWidth required error={!!errors.loanTerm}>
            <InputLabel>Loan Term (# Of Years)</InputLabel>
            <Select
              name="loanTerm"
              value={safeMortgageData.loanTerm}
              label="Loan Term (# Of Years)"
              onChange={handleChange}
            >
              <MenuItem value="15">15</MenuItem>
              <MenuItem value="20">20</MenuItem>
              <MenuItem value="30">30</MenuItem>
            </Select>
            {errors.loanTerm && (
              <Typography variant="caption" color="error">
                {errors.loanTerm}
              </Typography>
            )}
          </FormControl>
        </Grid>
        <FormTextField
          label="Down Payment"
          name="downPayment"
          type="number"
          value={safeMortgageData.downPayment}
          onChange={handleChange}
          error={errors.downPayment}
          helperText={errors.downPayment}
          icon={<AttachMoney color="primary" />}
          inputProps={{ min: 0, step: 1 }}
        />
        <FormTextField
          label="APN"
          name="apn"
          value={safeMortgageData.apn}
          onChange={handleChange}
          error={errors.apn}
          helperText={errors.apn}
          icon={<Description color="primary" />}
        />
        <FormTextField
          label="Entered By"
          name="enteredBy"
          value={safeMortgageData.enteredBy}
          onChange={handleChange}
          error={errors.enteredBy}
          helperText={errors.enteredBy}
          icon={<Person color="primary" />}
        />
      </SectionCard>

      <Box sx={{ mt: 4, display: "flex", justifyContent: "flex-end" }}>
        <Button
          type="submit"
          variant="contained"
          color="primary"
          size="large"
          endIcon={<ArrowForward />}
          disabled={isSubmitting}
          aria-label="Continue to next step"
          sx={{
            minWidth: 200,
            py: 1.5,
            borderRadius: 2,
            background: theme.palette.primary.main,
          }}
        >
          {isSubmitting ? "Processing..." : "Continue"}
        </Button>
      </Box>
    </Box>
  );
}

MortgageContract.propTypes = {
  onNext: PropTypes.func.isRequired,
};

export default MortgageContract;